-- Version history: register the import so it appears in the timeline and can be reverted.
CREATE TEMP TABLE import_ctx ON COMMIT DROP AS
SELECT gen_random_uuid() AS batch_id,
       (SELECT id FROM users WHERE role = 'admin' AND status = 'active' ORDER BY created_at LIMIT 1) AS actor_id;

INSERT INTO history_events (project_id, entity_type, entity_id, op, before, after, actor_id, batch_id, note)
SELECT p.id, 'project', p.id, 'create', NULL, jsonb_build_object(
    'id', p.id, 'name', p.name, 'description', p.description, 'status', p.status,
    'startDate', p.start_date, 'endDate', p.end_date, 'leaderName', p.leader_name, 'leaderEmail', p.leader_email,
    'version', p.version, 'deletedAt', NULL, 'createdAt', to_char(p.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), 'updatedAt', to_char(p.updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
  c.actor_id, c.batch_id, 'Geïmporteerd uit Excel: V01 - Stakeholders per fase.xlsx'
FROM projects p, import_ctx c WHERE p.id = '8fcbf8dd-4f3c-4055-a60f-04b0fc28a399';

INSERT INTO history_events (project_id, entity_type, entity_id, op, before, after, actor_id, batch_id, note)
SELECT f.project_id, 'phase', f.id, 'create', NULL, jsonb_build_object(
    'id', f.id, 'projectId', f.project_id, 'name', f.name, 'description', f.description, 'sortOrder', f.sort_order,
    'version', f.version, 'deletedAt', NULL, 'createdAt', to_char(f.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), 'updatedAt', to_char(f.updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
  c.actor_id, c.batch_id, 'Geïmporteerd uit Excel: V01 - Stakeholders per fase.xlsx'
FROM phases f, import_ctx c WHERE f.project_id = '8fcbf8dd-4f3c-4055-a60f-04b0fc28a399' ORDER BY f.sort_order;

INSERT INTO history_events (project_id, entity_type, entity_id, op, before, after, actor_id, batch_id, note)
SELECT s.project_id, 'stakeholder', s.id, 'create', NULL, jsonb_build_object(
    'id', s.id, 'projectId', s.project_id, 'phaseId', s.phase_id, 'sortOrder', s.sort_order, 'name', s.name,
    'contactPerson', s.contact_person, 'email', s.email, 'phone', s.phone, 'description', s.description,
    'deadline', s.deadline, 'activities', s.activities, 'interests', s.interests, 'status', s.status,
    'statusChangedBy', s.status_changed_by, 'statusChangedAt', NULL,
    'version', s.version, 'deletedAt', NULL, 'createdAt', to_char(s.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), 'updatedAt', to_char(s.updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
  c.actor_id, c.batch_id, 'Geïmporteerd uit Excel: V01 - Stakeholders per fase.xlsx'
FROM stakeholders s JOIN phases f ON f.id = s.phase_id, import_ctx c
WHERE s.project_id = '8fcbf8dd-4f3c-4055-a60f-04b0fc28a399' ORDER BY f.sort_order, s.sort_order;

COMMIT;
